import { ProCoinItem } from '@/types/pro'
import { Box, Flex, HStack, Text, VStack } from '@chakra-ui/react'
import { useVirtualizer, VirtualItem } from '@tanstack/react-virtual'
import React from 'react'
import Table from './Table'

// ------------------ 公共类型 ------------------

export interface Column<T> {
  key: keyof T | string // 列对应的字段名（允许是 T 的键，也可自定义）
  title: React.ReactNode
  render?: (row: T) => React.ReactNode // 可选的自定义渲染函数
  sticky?: boolean // 如果需要 sticky，给列单独标记
}

export interface VirtualTableProps<T> {
  columns: Column<T>[]
  data: T[]
  rowHeight?: number
  overscan?: number
  containerClassName?: string
  stickyHeaderTop?: string | number
  gridTemplateColumns: string
  columnGap?: string
  px?: string
  bg?: string
  isApp?: boolean
  scrollWidth?: string | number
  onRowClick: (item: any) => void
  isLoading?: boolean
}

// ------------------ VirtualTable 主组件 ------------------

export default function VirtualTable<T>({
  columns,
  data,
  rowHeight = 66,
  overscan = 100,
  containerClassName = '.scroll-container',
  stickyHeaderTop = 0,
  gridTemplateColumns,
  columnGap = '12px',
  px = '0 16px',
  bg = 'bg_primary',
  isApp = false,
  isLoading = false,
  scrollWidth = '830px',
  onRowClick
}: VirtualTableProps<T>) {
  const rowVirtualizer = useVirtualizer({
    count: data?.length,
    getScrollElement: () => document.querySelector(containerClassName) as HTMLElement | null,
    estimateSize: () => rowHeight,
    overscan
  })

  const renderHeader = () => (
    <Box
      as="div"
      display="grid"
      w="100%"
      gridTemplateColumns={gridTemplateColumns}
      h="36px"
      columnGap={isApp ? '0px' : columnGap}
      p={isApp ? 0 : px}
      position={isApp ? 'unset' : 'sticky'}
      top={stickyHeaderTop}
      zIndex="10"
      bg={bg}
    >
      {columns.map((col, index) => (
        <Flex
          key={String(col.key)}
          align="center"
          justify={index === columns.length - 1 ? 'flex-end' : 'flex-start'}
          position={isApp && col.sticky ? 'sticky' : 'static'}
          left="0"
          right="0"
          bg={isApp && col.sticky ? bg : 'inherit'}
          zIndex={isApp && col.sticky ? 2 : 1}
          pl={isApp && !col.sticky ? '12px' : '0px'}
        >
          {col.title}
        </Flex>
      ))}
    </Box>
  )

  return (
    <VStack w="100%" gap="0" align="stretch">
      {isLoading ? (
        <Table<ProCoinItem>
          rowKey="coinType"
          columns={columns}
          dataSource={data}
          skeletonLength={10}
          loading={true}
          rowStyle={{ h: '66px', cursor: 'pointer' }}
        />
      ) : isApp ? (
        <Box w="100%" overflowX="auto" bg={bg}>
          <Box w={scrollWidth}>
            {renderHeader()}
            <Box w="100%" h={`${rowVirtualizer.getTotalSize()}px`} pos="relative">
              {rowVirtualizer.getVirtualItems().map(virtualRow => (
                <CoinItem<T>
                  key={(data[virtualRow.index] as any)?.coinType ?? virtualRow.index}
                  item={data[virtualRow.index]}
                  columns={columns}
                  virtualRow={virtualRow}
                  gridTemplateColumns={gridTemplateColumns}
                  onRowClick={onRowClick}
                  isApp={isApp}
                  bg={bg}
                />
              ))}
            </Box>
          </Box>
        </Box>
      ) : (
        <>
          {renderHeader()}
          <Box w="100%" h={`${rowVirtualizer.getTotalSize()}px`} pos="relative">
            {rowVirtualizer.getVirtualItems().map(virtualRow => (
              <CoinItem<T>
                key={(data[virtualRow.index] as any)?.coinType ?? virtualRow.index}
                item={data[virtualRow.index]}
                columns={columns}
                virtualRow={virtualRow}
                gridTemplateColumns={gridTemplateColumns}
                onRowClick={onRowClick}
                isApp={isApp}
                bg={bg}
              />
            ))}
          </Box>
        </>
      )}
    </VStack>
  )
}

// ------------------  CoinItem 组件 ------------------

interface CoinItemProps<T> {
  item: T
  columns: Column<T>[]
  virtualRow: VirtualItem
  onRowClick: (item: any) => void
  bg: string
  isApp?: boolean
  gridTemplateColumns: string
}

function CoinItem<T>({ item, columns, virtualRow, onRowClick, isApp = false, gridTemplateColumns, bg }: CoinItemProps<T>) {
  return (
    <Box
      as="div"
      pos="absolute"
      top={`${virtualRow.start}px`}
      left="0"
      w="100%"
      h="66px"
      p="0px"
      borderRadius="12px"
      onClick={() => {
        onRowClick(item as any)
      }}
    >
      <HStack
        display="grid"
        w="100%"
        h="100%"
        cursor="pointer"
        columnGap={isApp ? '0px' : '12px'}
        gridTemplateColumns={gridTemplateColumns}
        borderRadius="12px"
        p={{ base: '0', lg: '0 16px' }}
        _hover={{
          bg: isApp ? 'auto' : 'primary_opacity.10'
        }}
      >
        {columns.map((col, index) => (
          <Flex
            align="center"
            key={String(col.key)}
            justify={index === columns.length - 1 ? 'flex-end' : 'flex-start'}
            position={isApp && col.sticky ? 'sticky' : 'static'}
            right={0}
            left={0}
            bg={isApp ? bg : 'unset'}
            zIndex={isApp && col.sticky ? 2 : 1}
            h="100%"
            pl={isApp && !col.sticky ? '12px' : '0px'}
          >
            {col.render ? (
              col.render(item)
            ) : (
              <Text fontSize="14px" fontWeight="500" color="text_caption">
                {(item as any)?.[col.key as keyof T] as string | number}
              </Text>
            )}
          </Flex>
        ))}
      </HStack>
    </Box>
  )
}
