import useProListStore from '@/store/pro/list'
import { SelectTab } from '@cetus/design'
import { Tab } from '@cetus/design/src/components/common/SelectTab'
import { RefreshButton } from '@cetus/ui-kit'
import { Box, HStack } from '@chakra-ui/react'
import ProSearch from './ProSearch'

function ProTab({ isApp, handleRefresh }: { isApp: boolean; handleRefresh: () => void }) {
  const { currentProTab, setCurrentProTab, setCurrentSortTab, setProListParams, proListParams } = useProListStore()
  const tabList: Tab[] = [
    {
      label: 'Trending'
      // beforeIcon: { xlinkHref: '#icon-icon_gainers', fontSize: '16px', activeColor: '#75C8FF', activeHoverColor: '#75C8FF', svgHover: '#75C8FF' }
    },
    {
      label: 'New'
      // beforeIcon: { xlinkHref: '#icon-icon_hot', fontSize: '16px', activeColor: '#75C8FF', activeHoverColor: '#75C8FF', svgHover: '#75C8FF' }
    },
    {
      label: 'Watchlist'
      // beforeIcon: { xlinkHref: '#icon-icon_star', fontSize: '16px', activeColor: '#75C8FF', activeHoverColor: '#75C8FF' }
    }
  ]

  const handleChange = (value: string) => {
    setCurrentProTab(value)
    if (value === 'Trending') {
      setCurrentSortTab('Gainers')
      setProListParams({
        ...proListParams,
        sorted_by: 'change',
        desc: true,
        tag: 'trending',
        volume_min: '',
        volume_max: '',
        liqidity_min: '10000',
        liqidity_max: '',
        market_cap_min: '10000',
        market_cap_max: '',
        offset: 0
      })
    } else if (value === 'New') {
      console.log('🚀 ~ handleChange ~ value:', value)
      setProListParams({
        ...proListParams,
        sorted_by: 'age',
        desc: true,
        tag: 'new',
        volume_min: '',
        volume_max: '',
        liqidity_min: '10',
        liqidity_max: '',
        market_cap_min: '',
        market_cap_max: '',
        offset: 0
      })
    }
  }

  return (
    <HStack w="100%" justify="space-between" borderBottom="1px solid" borderColor="border">
      <SelectTab
        type="borderTab"
        wrapStyle={{
          w: {
            base: '100%',
            lg: 'unset'
          },
          h: isApp ? '36px' : '68px',
          bg: 'none',
          border: 'none'
        }}
        itemStyle={{
          marginRight: {
            base: '24px',
            lg: '40px'
          },
          fontSize: '16px',
          position: 'relative',
          flex: isApp ? '1' : 'auto'
          // width: isApp ? 'auto' : '60px'
        }}
        tabList={tabList}
        currentTab={currentProTab}
        handleChangeTab={item => {
          handleChange(item.label as string)
        }}
      />
      <Box flex="1" />
      {!isApp && <ProSearch />}
      {!isApp && <RefreshButton handleRefresh={handleRefresh} w="32px" h="32px" innerStyle={{ bg: 'bg_secondary' }} />}
    </HStack>
  )
}

export default ProTab
